// Parse wpscan --format json output into a structured object the parent
// workflow's deterministic report builder can consume. wpscan exits non-zero
// when it finds vulns or hits an internal abort - onError:continueRegularOutput
// on the previous node means stdout still reaches us either way.
const raw = ($json.stdout || '').trim();
const origin = $json.origin || ($('When Called').item.json.origin);

let d;
try {
  const start = raw.indexOf('{');
  d = start >= 0 ? JSON.parse(raw.slice(start)) : null;
} catch (e) {
  d = null;
}

if (!d) {
  return [{ json: { ran: false, error: 'wpscan produced no usable output (timeout, abort, or command failure)', stderrExcerpt: ($json.stderr || '').slice(0, 500) } }];
}
if (d.scan_aborted) {
  return [{ json: { ran: false, error: d.scan_aborted } }];
}

const vulnList = (arr) => (arr || []).map(v => {
  const r = v.references || {};
  const cves = (r.cve || []).map(c => 'CVE-' + c);
  return {
    title: v.title,
    fixedIn: v.fixed_in || null,
    cve: cves[0] || null,
    hasExploit: !!((r.metasploit || []).length) || !!((r.exploitdb || []).length),
    refs: [].concat(cves, r.url || []).slice(0, 6),
  };
});

const core = d.version || {};
const mainTheme = d.main_theme || {};

const plugins = Object.entries(d.plugins || {}).map(([slug, p]) => ({
  slug,
  version: (p.version && p.version.number) || null,
  outdated: !!p.outdated,
  latestVersion: p.latest_version || null,
  vulns: vulnList(p.vulnerabilities),
}));
const themes = Object.entries(d.themes || {}).map(([slug, t]) => ({
  slug,
  version: (t.version && t.version.number) || null,
  outdated: !!t.outdated,
  vulns: vulnList(t.vulnerabilities),
}));

const users = Object.keys(d.users || {});

const findings = (d.interesting_findings || []).map(f => ({
  type: f.type,
  detail: f.to_s,
  url: f.url,
  metasploit: (f.references && f.references.metasploit) || [],
}));
const hasType = (t) => findings.some(f => f.type === t);

const backups = Object.keys(d.config_backups || {});
const dbExports = Object.keys(d.db_exports || {});

// Vuln data is added by the Enrich WP Vulns (NVD) node downstream, not
// wpscan (which needs a paid token for that). wpscan here is enumeration only.
return [{ json: {
  ran: true,
  origin,
  coreVersion: core.number || null,
  coreStatus: core.status || null,
  coreVulns: vulnList(core.vulnerabilities),
  mainTheme: { slug: mainTheme.slug || null, version: (mainTheme.version && mainTheme.version.number) || null, outdated: !!mainTheme.outdated, vulns: vulnList(mainTheme.vulnerabilities) },
  plugins,
  themes,
  users,
  xmlrpcEnabled: hasType('xmlrpc'),
  readmeExposed: hasType('readme'),
  wpCronEnabled: hasType('wp_cron'),
  uploadDirListing: hasType('upload_directory_listing'),
  configBackups: backups,
  dbExports,
  interestingFindings: findings,
  vulnDataAvailable: false,
  vulnSource: null,
  requestsDone: d.requests_done || null,
} }];

const wp = $json;
if (!wp.ran) return [{ json: wp }];

let key = null;
try { key = ($env && $env.NVD_API_KEY) || null; } catch (e) { key = null; }
const gap = key ? 800 : 6500;            // NVD: 5 req / 30s unauthenticated
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

const nvd = async (params) => {
  try {
    const opts = { method: 'GET', url: 'https://services.nvd.nist.gov/rest/json/cves/2.0?' + params, timeout: 25000, json: true };
    if (key) opts.headers = { apiKey: key };
    return await this.helpers.httpRequest(opts);
  } catch (e) { return null; }
};

const cvss = (m) => {
  if (!m) return null;
  const p = (a) => a && a[0] && a[0].cvssData && a[0].cvssData.baseScore;
  return p(m.cvssMetricV31) ?? p(m.cvssMetricV30) ?? p(m.cvssMetricV2) ?? null;
};
const isPureDos = (m) => {
  const cd = m && ((m.cvssMetricV31 || [])[0] || (m.cvssMetricV30 || [])[0] || {}).cvssData;
  return !!cd && cd.availabilityImpact === 'HIGH' && cd.confidentialityImpact === 'NONE' && cd.integrityImpact === 'NONE';
};
const toVuln = (entry) => {
  const c = entry.cve;
  const refs = c.references || [];
  const exploitRefs = refs.filter(r => (r.tags || []).includes('Exploit') || /exploit-db\.com|metasploit|packetstorm|0day\.today/i.test(r.url || ''));
  return {
    cve: c.id,
    title: ((c.descriptions || []).find(x => x.lang === 'en') || {}).value ? ((c.descriptions.find(x => x.lang === 'en').value).slice(0, 150)) : c.id,
    cvss: cvss(c.metrics),
    hasExploit: exploitRefs.length > 0 || !!c.cisaExploitAdd,
    kev: !!c.cisaExploitAdd,
    isDos: isPureDos(c.metrics),
    refs: [...new Set([].concat(c.id ? ['https://nvd.nist.gov/vuln/detail/' + c.id] : [], exploitRefs.map(r => r.url)))].slice(0, 4),
  };
};
const sortVulns = (vs) => vs
  .sort((a, b) => (b.hasExploit ? 1 : 0) - (a.hasExploit ? 1 : 0) || (b.cvss || 0) - (a.cvss || 0));

// Core: CPE match against the NVD dictionary is reliable for WordPress core.
let coreVulns = [];
if (wp.coreVersion) {
  const r = await nvd(`virtualMatchString=cpe:2.3:a:wordpress:wordpress:${encodeURIComponent(wp.coreVersion)}&resultsPerPage=200`);
  if (r && r.vulnerabilities) {
    const namesComponent = (e) => {
      const desc = ((e.cve.descriptions || []).find(x => x.lang === 'en') || {}).value || '';
      return /\bfor (the )?[\w -]+? (plugin|theme)\b/i.test(desc) || /^The [\w -]+ (plugin|theme) (for WordPress )?(through|before|version)/i.test(desc);
    };
    coreVulns = sortVulns(r.vulnerabilities.filter(e => !namesComponent(e)).map(toVuln));
  }
  await sleep(gap);
}

wp.coreVulns = coreVulns;
wp.vulnDataAvailable = true;
wp.vulnSource = 'NVD (services.nvd.nist.gov, CPE match on core version)';
// Plugin/theme CVE attribution by name is unreliable (NVD CPE vendor names for
// WP plugins are inconsistent) - left to a searchsploit dispatch bullet per
// outdated component in Section 6 rather than risking a wrong CVE match here.
wp.componentCveLookup = 'core only (plugins/themes -> searchsploit follow-up)';

return [{ json: wp }];
